import {DEFAULTS,CONTRACT,addDays,cohort,metrics,trendSeries,routeComparison,departureRows,validateDataset,checkContext,periodComparison,exploreBookings} from './analytics.mjs';
import {createWorlds,evaluate,SEED} from './model.mjs';
import {createEmailActions} from './email-actions.mjs';
import {createPolicyActions} from './policy-actions.mjs';

const root=document.querySelector('#view'),message=document.querySelector('#global-message');
let data=null,loadTime=null,loading=false;
const policies=new Map();
const validViews=['overview','pace','mix','detail','model'];
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,d=0)=>v===null?'N/A':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:d,maximumFractionDigits:d}).format(v);
const number=(v,d=0)=>v===null?'N/A':new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(v);
const percent=v=>v===null?'N/A':number(v,2)+'%';
const shortDate=date=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(date+'T00:00:00Z'));
const fullDate=date=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T00:00:00Z'));
function readState(){const p=new URLSearchParams(location.search),s={...DEFAULTS,booking:''};for(const k of Object.keys(s))if(p.has(k))s[k]=p.get(k);if(!validViews.includes(s.view))s.view='overview';return s;}
let state=readState();
const emailActions=createEmailActions({getContext:()=>({data,state}),navigate});
const policyActions=createPolicyActions({getContext:()=>({data,state}),getHeaders:emailActions.getHeaders,setPolicy:(id,price,{resetAssumptions=false}={})=>{
  const f=data.flights.find(f=>f.id===id);if(!f)return;
  const p=policies.get(id)||{};
  policies.set(id,{...p,price,...(resetAssumptions?{protect:Math.min(3,f.mintCapacity-f.mintBooked),cannibalization:.15,demand:1}:{})});
  if(state.flight!==id||!document.querySelector('#scenario-form'))return;
  document.querySelector('#upgrade-price').value=price;
  if(resetAssumptions){document.querySelector('#protected-seats').value=Math.min(3,f.mintCapacity-f.mintBooked);document.querySelector('#switching-rate').value=15;document.querySelector('#demand-level').value='1';}
  runScenario();
}});
function navigate(changes,{replace=false,focusId=null,preserveFilters=false}={}){
  if(['route','from','to','asof','channel','q','sort'].some(k=>k in changes)&&!('page' in changes))changes.page='1';
  state={...state,...changes};const p=new URLSearchParams();for(const [k,v] of Object.entries(state))if(v!==''&&v!==DEFAULTS[k])p.set(k,v);
  history[replace?'replaceState':'pushState']({},'',location.pathname+(p.size?'?'+p.toString():''));
  message.innerHTML='';render({preserveFilters});
  if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
  else if(changes.view)focusHeading();
  window.scrollTo({top:0,behavior:'instant'});
}
function focusHeading(){const title=root.querySelector('h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}}
function breadcrumbs(){
  if(state.view==='overview')return '';
  const back=state.view==='detail'?(state.back==='mix'?'mix':'pace'):null;
  return `<div class="breadcrumbs"><button data-action="overview">Overview</button><span>›</span>${back?`<button data-action="${back}">${back==='mix'?'Fare & channel mix':'Booking pace'}</button><span>›</span>`:''}<span>${state.view==='detail'?e(state.flight):({pace:'Booking pace',mix:'Fare & channel mix',model:'Data & model'}[state.view])}</span>${state.route!=='all'?`<span>· ${e(state.route)}</span>`:''}</div>`;
}
function heading(title,subtitle,eyebrow='PORTFOLIO / MINT'){
  return `${breadcrumbs()}<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subheading">${subtitle}</p></div><div class="meta-badge">Synthetic data · ${e(data.meta.contractVersion||CONTRACT)}</div></div>`;
}
function filters(){
  return `<form class="filter-bar" id="filters" aria-label="Shared analytics filters"><div class="field"><label for="route-filter">Route market</label><select id="route-filter" name="route"><option value="all">All six routes</option>${data.routes.map(r=>`<option value="${e(r.id)}"${state.route===r.id?' selected':''}>${e(r.id)}</option>`).join('')}</select></div><div class="field"><label for="departure-from">Departures from</label><input id="departure-from" name="from" type="date" value="${e(state.from)}" required></div><div class="field"><label for="departure-to">Departures through</label><input id="departure-to" name="to" type="date" value="${e(state.to)}" required></div><div class="field"><label for="asof-date">Data as of</label><input id="asof-date" name="asof" type="date" min="2026-10-12" max="${e(data.meta.asOf)}" value="${e(state.asof)}" required></div><span class="filter-note">${cohort(data,state).length} fictional departures · USD</span><button type="button" class="reset-button" data-action="reset">Reset</button></form>`+activeFilters();
}
function activeFilters(){
  const count=cohort(data,state).length;
  return `<section class="active-filters" aria-label="Active filter summary"><strong>Viewing ${count} fictional ${count===1?'departure':'departures'}</strong><span>${state.route==='all'?'All six routes':e(state.route)}</span><span>Departures: ${fullDate(state.from)} – ${fullDate(state.to)}</span><span>As of: ${fullDate(state.asof)}</span>${state.view==='overview'?'<span>All booking channels · USD</span>':''}</section>`;
}
function metricCard(label,value,context,action,scope=false){const key=({'Booked Mint revenue':'revenue','Booked seat utilization':'utilization','Remaining Mint seats':'remaining','7-day booking pickup':'pickup'})[label];return `<${action?'button':'div'} class="metric-card"${action?` type="button" data-action="finding" data-metric="${key}" data-next="${action}" aria-haspopup="menu" aria-expanded="false"`:''}><div class="metric-label">${label}${scope?' <span class="scope">All channels</span>':''}</div><div class="metric-value">${value}</div><div class="metric-context">${context}</div>${action?`<span class="metric-next">Explore or share finding →</span>`:''}</${action?'button':'div'}>`;}
function coreCards(m){
  return `<section class="metrics" aria-label="Portfolio key performance indicators">${metricCard('Booked Mint revenue',money(m.revenue),`<span class="delta">+${money(m.recentRevenue)}</span> booked ${shortDate(addDays(state.asof,-6))}–${shortDate(state.asof)}`,'mix')}${metricCard('Booked seat utilization',percent(m.utilization),`${number(m.bookedAll)} booked / ${number(m.capacity)} modeled seats`,'pace',true)}${metricCard('Remaining Mint seats',number(m.remaining),'Point-in-time inventory · selected departures','pace',true)}${metricCard('7-day booking pickup',number(m.pickup),m.priorPickup===null?'Prior window unavailable · incomplete history':`${shortDate(addDays(state.asof,-6))}–${shortDate(state.asof)} · <span class="delta">vs ${number(m.priorPickup)}</span> on ${shortDate(addDays(state.asof,-13))}–${shortDate(addDays(state.asof,-7))}`,'pickup')}</section>`;
}
function empty(title='No departures match these filters',detail='Adjust the route or departure dates to return to your portfolio.'){
  return `<div class="empty-state"><h2>${title}</h2><p>${detail}</p><button class="button primary" data-action="reset">Reset filters</button></div>`;
}
function lineChart(points,{title='Booking history',subtitle='Cumulative booked Mint passengers · same departure cohort',detail=false}={}){
  if(!points.length)return '';
  const w=620,h=270,L=42,R=25,T=30,B=37,rawMax=Math.max(...points.map(p=>p.booked)),step=rawMax<=20?4:rawMax<=100?20:100,max=Math.max(step,Math.ceil(rawMax/step)*step),usable=w-L-R;
  const coords=points.map((p,i)=>({x:L+(points.length===1?.5:i/(points.length-1))*usable,y:T+(1-p.booked/max)*(h-T-B),p}));
  const path=coords.map((c,i)=>(i?'L':'M')+c.x.toFixed(2)+','+c.y.toFixed(2)).join(' ');
  const tickIndices=[...new Set([0,Math.max(0,points.length-8),points.length-1])];
  const grid=Array.from({length:5},(_,i)=>{const val=max*i/4,y=T+(1-i/4)*(h-T-B);return `<line x1="${L}" x2="${w-R}" y1="${y}" y2="${y}" stroke="#e5ebf0"/><text x="${L-10}" y="${y+4}" text-anchor="end">${number(val)}</text>`;}).join('');
  const circles=coords.map((c,i)=>`<a href="?view=pace&amp;focus=${c.p.date}" data-action="focus" data-date="${c.p.date}" aria-label="Inspect ${shortDate(c.p.date)}: ${c.p.booked} Mint passengers booked"><circle cx="${c.x}" cy="${c.y}" r="${i===points.length-1?5:4}" fill="#0000AA"/><title>${fullDate(c.p.date)}: ${c.p.booked} passengers</title></a>`).join('');
  const ticks=tickIndices.map(i=>`<text x="${coords[i].x}" y="${h-10}" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}">${shortDate(points[i].date)}</text>`).join('');
  const labels=[...new Set([points.length-1,Math.max(0,points.length-8)])].map(i=>`<text class="line-value" x="${coords[i].x}" y="${Math.max(17,coords[i].y-12)}" text-anchor="${i===points.length-1?'end':'middle'}">${points[i].booked}</text>`).join('');
  return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p class="panel-subtitle">${subtitle}</p></div>${!detail?'<button class="text-button" data-action="pace">Explore pace ↗</button>':''}</div><svg class="line-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${e(title)}: ${points[0].booked} passengers on ${shortDate(points[0].date)}, rising to ${points.at(-1).booked} on ${shortDate(points.at(-1).date)}.">${grid}<path d="${path}" fill="none" stroke="#0000AA" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${circles}${ticks}${labels}</svg><p class="panel-footnote">${points.length} observation dates · Calendar time · No forecast${points.length<14?' · Shortened trend: complete cohort history begins '+fullDate(points[0].date):''}</p><details class="chart-data"><summary>View values and date actions</summary><table><thead><tr><th>Date</th><th class="num">Booked passengers</th><th>Next step</th></tr></thead><tbody>${points.map(p=>`<tr><td>${fullDate(p.date)}</td><td class="num">${p.booked}</td><td><button class="row-link" data-action="focus" data-date="${p.date}">Inspect this date</button></td></tr>`).join('')}</tbody></table></details></section>`;
}
function routeBars(rows,{kind='remaining',title='Where are the unsold seats?',subtitle='Remaining Mint seats by route · all channels'}={}){
  const max=Math.max(1,...rows.map(r=>kind==='average'?r.average:r.remaining)),axis=Math.ceil(max/(kind==='average'?500:20))*(kind==='average'?500:20);
  return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p class="panel-subtitle">${subtitle}</p></div></div><div class="route-bars">${rows.map(r=>{const value=kind==='average'?r.average:r.remaining;return `<button class="route-row"${kind==='average'?' style="grid-template-columns:75px minmax(0,1fr) 65px"':''} data-action="${kind==='average'?'mix-route':'route'}" data-route="${e(r.id)}" aria-label="${e(r.id)}: ${kind==='average'?money(value,2)+' average booked fare':value+' remaining seats'}. ${kind==='average'?'Filter fare analysis':'Explore booking pace'}"><span>${e(r.id)}</span><span class="bar-track"><span class="bar" style="width:${value===null?0:100*value/axis}%"></span></span><span class="route-value"${kind==='average'?' style="min-width:60px"':''}>${kind==='average'?money(value):number(value)}</span></button>${kind==='remaining'?`<p class="route-exposure">${r.flights.length} departures · ${r.remaining} / ${r.capacity} seats remaining (${percent(100*r.remaining/r.capacity)})</p>`:''}`;}).join('')}</div><div class="route-axis">${[0,.25,.5,.75,1].map(p=>`<span>${kind==='average'?money(axis*p):number(axis*p)}</span>`).join('')}</div><p class="panel-footnote">${kind==='average'?'USD per booked passenger · Weighted from booking records':'Seats remaining at '+shortDate(state.asof)+' · Inventory, not an uplift score'}</p></section>`;
}
function departureTable(rows,{overview=false,title='Departure records'}={}){
  const shown=overview?rows.slice(0,4):rows;
  return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2><p class="panel-subtitle">${overview?`${rows.length} departures within 7 days · showing ${shown.length} · sorted by remaining seats`:`${rows.length} departures · inventory across all booking channels`}</p></div>${overview?'<button class="text-button" data-action="pace">View all departures ↗</button>':''}</div>${rows.length?`<div class="table-wrap"><table class="review-table"><thead><tr><th>Departure</th><th>Route</th><th>Date</th><th class="num">Booked / capacity</th><th class="num">Remaining</th><th class="num">7-day pickup</th><th>Next step</th></tr></thead><tbody>${shown.map(f=>`<tr${f.id===state.flight?' class="record-highlight"':''}><td data-label="Departure"><span class="mono">${e(f.id)}</span></td><td data-label="Route"><span class="route-label">${e(f.routeId)}</span></td><td data-label="Departure date">${shortDate(f.departure)} <small style="color:var(--muted)">· ${number(Math.round((Date.parse(f.departure)-Date.parse(state.asof))/86400000))}d out</small></td><td class="num" data-label="Booked / capacity">${f.asofBooked} / ${f.mintCapacity}</td><td class="num" data-label="Remaining seats"><span class="pill">${f.remaining} seats</span></td><td class="num" data-label="7-day pickup">${f.pickup}</td><td data-label="Next step"><button class="row-link" data-action="${overview?'investigate':'detail'}" data-flight="${e(f.id)}">${overview?'Investigate pace':'Open departure'} →</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="data-description">No departures fall within the next seven days for this as-of date. The full departure cohort is still available in Booking pace.</p>'}</section>`;
}
function overviewContext(){
  const m=metrics(data,state),comparison=m.priorPickup===null?`Current pickup: ${fullDate(addDays(state.asof,-6))} – ${fullDate(state.asof)} (7 days). Prior 7-day window unavailable: history is incomplete; no partial-period comparison is shown.`:`Pickup comparison: ${shortDate(addDays(state.asof,-6))}–${shortDate(state.asof)} vs ${shortDate(addDays(state.asof,-13))}–${shortDate(addDays(state.asof,-7))}, ${state.asof.slice(0,4)} · 7 days each · same ${m.flights.length}-departure cohort.`;
  const lastRead=loadTime?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}).format(loadTime):'not yet recorded';
  return `<section class="overview-context" aria-label="Data freshness and metric help"><div class="freshness-line"><span><span class="freshness-dot" aria-hidden="true"></span><strong>Synthetic dataset</strong> · Coverage through ${fullDate(data.meta.asOf)}</span><span id="last-read">Last successful read: ${e(lastRead)} · Manual refresh</span></div><p class="comparison-status">${comparison}</p><details class="metric-help"><summary>Metric definitions & comparison basis</summary><dl class="metric-definitions"><div><dt>Booked Mint revenue · USD</dt><dd>Sum of generated Mint ticket fares booked on or before the selected as-of date, for the selected departures. Recent booking revenue is a subset of that cumulative total.</dd></div><div><dt>Booked seat utilization · percent</dt><dd>Booked Mint passengers at the selected date ÷ modeled Mint capacity × 100. Capacity is counted once per departure, across all channels. This is booked utilization, not final flown load factor.</dd></div><div><dt>Remaining Mint seats · seats</dt><dd>Modeled capacity minus booked Mint passengers at the selected date. This is a point-in-time balance across all channels; do not add balances across dates.</dd></div><div><dt>7-day booking pickup · passengers</dt><dd>New bookings from ${fullDate(addDays(state.asof,-6))} through ${fullDate(state.asof)}, compared with ${fullDate(addDays(state.asof,-13))} through ${fullDate(addDays(state.asof,-7))} for the same departure cohort. No cancellations or refunds are modeled.</dd></div></dl><p class="help-note">Prior-period comparisons appear only when complete history exists. No target has been assumed. Source coverage and successful read time are separate: refreshing does not create newer business data. Empty cohorts show an explanation instead of KPI cards; zero denominators show N/A.</p></details></section>`;
}

function comparisonMode(){
  const c=periodComparison(data,state);
  return `<section class="comparison-mode panel" aria-label="Optional booking-week comparison"><div class="comparison-toolbar"><div><h2>Compare booking weeks</h2><p class="panel-subtitle">A supplementary flow comparison; headline revenue stays cumulative.</p></div><div class="field"><label for="comparison-mode">Comparison mode</label><select id="comparison-mode"><option value="none"${state.compare==='none'?' selected':''}>No additional comparison</option><option value="prior7"${state.compare==='prior7'?' selected':''}>Previous 7 booking days</option></select></div></div>${state.compare==='prior7'?(c.available?`<p class="comparison-basis">${fullDate(c.start)}–${fullDate(c.end)} versus ${fullDate(c.priorStart)}–${fullDate(c.priorEnd)} · 7 days each · same ${c.departures} departures · all channels</p><div class="table-wrap"><table id="period-comparison"><caption>Bookings received in equivalent seven-day windows</caption><thead><tr><th>Measure</th><th class="num">Current 7 days</th><th class="num">Prior 7 days</th><th class="num">Difference</th></tr></thead><tbody><tr><th scope="row">Booking pickup · passengers</th><td class="num">${c.currentCount}</td><td class="num">${c.priorCount}</td><td class="num">${c.currentCount-c.priorCount>=0?'+':''}${c.currentCount-c.priorCount} (${c.priorCount?number(100*(c.currentCount-c.priorCount)/c.priorCount,1)+'%':'N/A: prior is zero'})</td></tr><tr><th scope="row">New booked fares · USD</th><td class="num">${money(c.currentRevenue)}</td><td class="num">${money(c.priorRevenue)}</td><td class="num">${money(c.currentRevenue-c.priorRevenue)}</td></tr></tbody></table></div><p class="panel-footnote">Source: synthetic booking events. No target or external benchmark is assumed. No cancellations or refunds are modeled; faster pickup does not establish a pricing effect.</p>`:`<p class="notice">Comparison unavailable: ${c.departures?'the prior seven-day window has incomplete history':'no departures match the filters'}. No partial period or zero substitute is shown.</p>`):''}</section>`;
}
function decisionBrief(m){
  const markets=routeComparison(data,state),lead=markets[0],nearest=departureRows(data,state).sort((a,b)=>a.departure.localeCompare(b.departure)||b.remaining-a.remaining)[0];
  const nearestBookings=m.allBookings.filter(b=>b.flightId===nearest.id),nearestRevenue=nearestBookings.reduce((n,b)=>n+b.fare,0);
  return `<details class="decision-brief panel"><summary>Scenario insights & recommended next steps</summary><p class="panel-subtitle">Generated scenario observations · selected cohort · as of ${fullDate(state.asof)}. These are not real JetBlue results.</p><ol class="insight-list"><li><h3>Booking momentum</h3><p>${m.priorPickup===null?'The prior window is incomplete; no momentum comparison is supported.':`${m.pickup} bookings on ${shortDate(addDays(state.asof,-6))}–${shortDate(state.asof)} versus ${m.priorPickup} on ${shortDate(addDays(state.asof,-13))}–${shortDate(addDays(state.asof,-7))}: ${m.pickup-m.priorPickup>=0?'+':''}${m.pickup-m.priorPickup} passengers across the same ${m.flights.length} departures.`} Calendar proximity and generated seasonality can explain this association; it is not proof of a pricing effect.</p><button class="text-button" data-action="pace">Trace booking momentum →</button></li><li><h3>Inventory concentration</h3><p>${e(lead.id)} has ${lead.remaining} / ${lead.capacity} Mint seats remaining (${percent(100*lead.remaining/lead.capacity)}) across ${lead.flights.length} departures${markets.length>1?', the largest absolute remaining inventory in this selection':''}. That is ${percent(100*lead.remaining/m.remaining)} of the selected remaining seats. A seat count alone does not measure lost revenue or future demand.</p><button class="text-button" data-action="route" data-route="${e(lead.id)}">Inspect ${e(lead.id)} inventory →</button></li><li><h3>A record-supported departure to inspect</h3><p>${e(nearest.id)} · ${e(nearest.routeId)} · ${fullDate(nearest.departure)} has ${nearest.remaining} of ${nearest.mintCapacity} seats remaining. Its ${nearestBookings.length} booked passengers total ${money(nearestRevenue)}. Review the supporting records and scenario assumptions before choosing an upgrade offer.</p><button class="text-button" data-action="detail" data-flight="${e(nearest.id)}">Inspect ${e(nearest.id)} records & scenario →</button></li></ol><div class="decision-next"><strong>First action · Revenue Management analyst</strong><p>At this modeled checkpoint, inspect the nearest departure's booking pace and run low/base/high future-demand assumptions in the seat-policy lab. Prioritize this review before setting an upgrade fee. Expected value is unmeasured; effort is one departure review; confidence is high in the reconciled counts and low in the uncalibrated demand assumptions. Success measure for a real pilot: incremental total revenue versus a comparable holdout. Guardrail: do not sacrifice protected full-fare inventory without demand evidence. A validated demand forecast or a negative sensitivity result should change the recommendation.</p></div><p class="panel-footnote">Priority 2: review the leading inventory market with capacity normalization. Priority 3: compare channel mix within each route before attributing fare differences to channel. No operational action is automated.</p></details>`;
}

function renderOverview(){
  const m=metrics(data,state);
  return heading('The Mint portfolio, at a glance.','See what is booked, where inventory remains, and which departures deserve a closer look.')+filters()+(m.flights.length?coreCards(m)+overviewContext()+comparisonMode()+`<div class="two-panels">${lineChart(trendSeries(data,state))}${routeBars(routeComparison(data,state))}</div>`+decisionBrief(m)+departureTable(departureRows(data,state).filter(f=>Date.parse(f.departure)-Date.parse(state.asof)<=7*86400000).sort((a,b)=>b.remaining-a.remaining||a.departure.localeCompare(b.departure)),{overview:true,title:'Departures to inspect — next 7 days'}):empty());
}
function dailyPanel(flights){
  const ids=new Set(flights.map(f=>f.id)),days=trendSeries(data,state,flights.length===1?flights[0].id:null).map(p=>({date:p.date,count:data.bookings.filter(b=>ids.has(b.flightId)&&b.bookingDate===p.date).length})),max=Math.max(1,...days.map(d=>d.count));
  return `<section class="panel"><div class="panel-header"><div><h2>When did the bookings arrive?</h2><p class="panel-subtitle">Daily Mint bookings · passengers · selected cohort</p></div></div><div class="daily-bars">${days.map(d=>`<div class="daily-bar-row${state.focus===d.date?' focused':''}"><span>${shortDate(d.date)}</span><span class="bar-track"><span class="bar" style="width:${100*d.count/max}%"></span></span><strong class="num">${d.count}</strong></div>`).join('')}</div><p class="panel-footnote">Daily additions, not cumulative balances. The date focus is local to this diagnostic.</p></section>`;
}
function renderPace(){
  const m=metrics(data,state),focused=state.flight?m.flights.find(f=>f.id===state.flight):null,fs=focused?[focused]:m.flights;
  return heading('Understand the booking pace.','Follow the dates and departures behind the portfolio totals.','DIAGNOSTIC / BOOKING PACE')+filters()+(m.flights.length?`${state.focus?`<div class="notice">Focused date: <strong>${fullDate(state.focus)}</strong>. The global as-of cutoff remains ${fullDate(state.asof)}. <button class="text-button" data-action="clear-focus">Clear focus</button></div>`:''}${focused?`<div class="notice">Inspecting <strong>${e(focused.id)} · ${e(focused.routeId)}</strong> in the charts below. <button class="text-button" data-action="detail" data-flight="${e(focused.id)}">Open departure detail →</button><button class="text-button" data-action="clear-flight">Show full cohort</button></div>`:''}${coreCards(m)}<div class="two-panels">${lineChart(trendSeries(data,state,focused?.id),{title:focused?`${e(focused.id)} booking history`:'How has booked demand changed?',detail:true})}${dailyPanel(fs)}</div>${departureTable(departureRows(data,state).sort((a,b)=>a.departure.localeCompare(b.departure)||b.remaining-a.remaining))}`:empty());
}
function channelPanel(){
  const rows=['Direct','Travel partner'].map(source=>({source,...metrics(data,state,{channel:source})})),total=rows.reduce((n,r)=>n+r.booked,0);
  return `<section class="panel"><div class="panel-header"><div><h2>Which channels supplied the bookings?</h2><p class="panel-subtitle">All-channel comparison for the selected departures · click a channel</p></div></div>${rows.map(r=>`<button class="route-row" data-action="channel" data-channel="${e(r.source)}" style="grid-template-columns:100px 1fr 35px;margin:24px 0"><span>${e(r.source)}</span><span class="bar-track"><span class="bar" style="width:${total?100*r.booked/total:0}%"></span></span><strong class="num">${r.booked}</strong></button><p class="panel-footnote">${e(r.source)} · ${money(r.revenue)} booked · ${money(r.average,2)} average fare</p>`).join('')}<p class="panel-footnote">Unit: booked passengers. Channel selection filters booking measures only.</p></section>`;
}

function bookingTable(bookings,{detail=false}={}){
  const x=exploreBookings(bookings,state),allRevenue=bookings.reduce((n,b)=>n+b.fare,0),channel=state.view==='mix'||(detail&&state.back==='mix')?state.channel:'all';
  const selected=detail&&state.booking?bookings.find(b=>b.id===state.booking):null;
  return `<section class="panel booking-explorer"><div class="panel-header"><div><h2>${detail?'Supporting booking records':'Trace the fare mix to bookings'}</h2><p class="panel-subtitle">${x.rows.length} search results / ${bookings.length} cohort booking records · ${channel==='all'?'all channels':e(channel)}</p></div><button class="text-button" data-action="export-bookings">Export search results CSV ↓</button></div><form id="booking-search-form" class="explorer-controls"><div class="field"><label for="booking-search">Search booking records</label><input id="booking-search" type="search" name="q" maxlength="80" placeholder="ID, departure, date, channel or fare" value="${e(state.q)}"></div><button class="button" type="submit">Search</button><div class="field"><label for="booking-sort">Sort booking records</label><select id="booking-sort">${[['date-desc','Newest booking first'],['date-asc','Oldest booking first'],['fare-desc','Highest fare first'],['fare-asc','Lowest fare first']].map(([v,label])=>`<option value="${v}"${state.sort===v?' selected':''}>${label}</option>`).join('')}</select></div><button type="button" class="text-button" data-action="clear-search">Clear search</button></form><p class="record-totals" role="status">Search revenue: ${money(x.revenue)} · Full cohort booking revenue: ${money(allRevenue)}. Totals include all matching records, not just this page.</p>${state.booking&&detail?(selected?`<div class="selected-booking"><h3>Selected booking · ${e(selected.id)}</h3><p>${e(selected.flightId)} · ${fullDate(selected.bookingDate)} · ${e(selected.source)} · ${money(selected.fare)} Mint ticket fare. Synthetic booking record; not a paid-upgrade outcome.</p></div>`:'<div class="notice warning">That booking ID is not in this selected departure/channel/cutoff. The matching records below are unchanged.</div>'):''}${x.rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable booking record table"><table><caption>Matching synthetic Mint bookings · fare in USD</caption><thead><tr><th>Booking ID</th><th>Booked on</th><th>Channel</th><th class="num">Fare · USD</th><th>Departure / inspect</th></tr></thead><tbody>${x.shown.map(b=>`<tr${b.id===state.booking?' class="record-highlight"':''}><td>${e(b.id)}</td><td>${fullDate(b.bookingDate)}</td><td>${e(b.source)}</td><td class="num">${money(b.fare)}</td><td><button class="row-link" data-action="${detail?'select-booking':'booking'}" data-flight="${e(b.flightId)}" data-booking="${e(b.id)}">${e(b.flightId)} · inspect →</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><button class="button" data-action="record-page" data-page="${x.page-1}"${x.page<=1?' disabled':''}>Previous records</button><span>Page ${x.page} of ${x.pages} · ${x.shown.length} visible / ${x.rows.length} results</span><button class="button" data-action="record-page" data-page="${x.page+1}"${x.page>=x.pages?' disabled':''}>Next records</button></div>`:'<div class="notice">No booking records match this search. Clear search to restore the selected cohort. A zero search total does not mean the departure has no bookings.</div>'}</section>`;
}
function mixAnnotation(){
  const direct=metrics(data,state,{channel:'Direct'}),partner=metrics(data,state,{channel:'Travel partner'});
  return `<section class="notice hypothesis"><strong>Observation versus explanation</strong><p>Within the shared departure cohort, Direct has ${direct.booked} bookings at ${money(direct.average,2)} average fare; Travel partner has ${partner.booked} at ${money(partner.average,2)}. Hypothesis: channel mix may be associated with fare differences. Check the same route and equivalent booking dates for a counterexample before attributing the difference to channel. Route mix, booking lead time and small group sizes are possible confounders. Fare classes and causal evidence are not modeled.</p></section>`;
}
function renderMix(){
  const m=metrics(data,state,{channel:state.channel}),rows=data.routes.filter(r=>state.route==='all'||state.route===r.id).map(r=>({...r,...metrics(data,{...state,route:r.id},{channel:state.channel})})).filter(r=>r.flights.length).sort((a,b)=>(b.average||0)-(a.average||0));
  return heading('Look inside the fare mix.','Compare booked fares and channels, then trace an aggregate back to an individual booking.','DIAGNOSTIC / FARE & CHANNEL MIX')+filters()+(m.flights.length?`<div class="diagnostic-toolbar"><label for="channel-filter">Booking channel</label><select id="channel-filter"><option value="all">All channels</option>${['Direct','Travel partner'].map(s=>`<option${state.channel===s?' selected':''}>${e(s)}</option>`).join('')}</select><span class="data-description">Local to booking measures · shared departure filters preserved</span></div><section class="metrics">${metricCard('Booked Mint revenue',money(m.revenue),'Selected channel · cumulative through '+shortDate(state.asof))}${metricCard('Average booked fare',money(m.average,2),`${number(m.booked)} booked passengers · weighted average`)}${metricCard('Booked passengers',number(m.booked),'Supporting denominator · selected channel')}${metricCard('7-day booking pickup',number(m.pickup),'Selected channel · '+shortDate(addDays(state.asof,-6))+'–'+shortDate(state.asof))}</section><div class="two-panels">${routeBars(rows,{kind:'average',title:'How do booked fares compare?',subtitle:'Average booked Mint fare by route · USD / passenger'})}${channelPanel()}</div>${mixAnnotation()}${bookingTable(m.bookings)}`:empty());
}
function inventoryGrid(f,m){
  let cells='';for(let i=0;i<f.mintCapacity;i++){if(i%4===2)cells+='<span class="seat-aisle" aria-hidden="true"></span>';cells+=`<span class="seat${i<m.bookedAll?' booked':''}">${i+1}</span>`;}
  return `<section class="panel"><h2>Mint inventory</h2><p class="panel-subtitle">Illustrative ${f.mintCapacity}-seat grid · all channels</p><div class="seat-layout" aria-label="${m.bookedAll} booked of ${f.mintCapacity} modeled Mint seats">${cells}</div><div class="seat-map-legend"><span><i></i>Booked</span><span><i class="free"></i>Remaining</span></div><p class="panel-footnote">Marks represent counts, not actual seat assignments or aircraft layouts.</p><dl class="detail-info"><div><dt>Departure</dt><dd>${fullDate(f.departure)}</dd></div><div><dt>Local time</dt><dd>${e(f.departureTime)}</dd></div><div><dt>Remaining</dt><dd>${m.remaining} seats</dd></div><div><dt>7-day pickup</dt><dd>${m.pickup} passengers</dd></div></dl></section>`;
}
function simulationPanel(f){
  if(state.asof!==data.meta.asOf)return `<section class="panel simulation"><h2>Seat-policy scenario lab</h2><p class="panel-subtitle">Scenario assumptions are defined for the 10 Nov inventory snapshot. Select 10 Nov 2026 to use the lab.</p></section>`;
  const remaining=f.mintCapacity-f.mintBooked;
  const p=policies.get(f.id)||{price:450,protect:Math.min(3,remaining),cannibalization:.15,demand:1};policies.set(f.id,p);
  return `<section class="panel simulation"><div class="panel-header"><div><div class="eyebrow">SCENARIO EXTENSION / SYNTHETIC ASSUMPTIONS</div><h2>Sell the upgrade, or hold the seat?</h2><p class="panel-subtitle">Compare your offer with holding every remaining Mint seat for future full-fare requests.</p></div><span class="pill teal">240 paired scenarios</span></div><div class="notice warning">A teaching simulation, not a fitted JetBlue forecast. Results depend on the assumed demand, willingness to pay and customer switching. Existing booked revenue is common to both policies and excluded from the comparison.</div><form id="scenario-form" class="simulation-controls"><div><label for="upgrade-price">Upgrade fee · <output id="price-output">${money(p.price)}</output></label><input id="upgrade-price" name="price" type="range" min="250" max="1200" step="50" value="${p.price}"></div><div><label for="protected-seats">Protect for full fare · <output id="protect-output">${p.protect} seats</output></label><input id="protected-seats" name="protect" type="range" min="0" max="${remaining}" step="1" value="${p.protect}"></div><div><label for="demand-level">Assumed future demand</label><select id="demand-level" name="demand">${[[.6,'Low · 0.6×'],[1,'Base · 1.0×'],[1.4,'High · 1.4×']].map(([v,l])=>`<option value="${v}"${p.demand===v?' selected':''}>${l}</option>`).join('')}</select></div><div><label for="switching-rate">Potential full-fare switching · <output id="switch-output">${Math.round(p.cannibalization*100)}%</output></label><input id="switching-rate" name="cannibalization" type="range" min="0" max="40" step="5" value="${p.cannibalization*100}"></div></form><div id="scenario-results" aria-live="polite"></div><details><summary>See the assumptions and revenue accounting</summary><ul><li>One upgrade offer happens now, followed by modeled full-fare demand. This is a one-stage policy comparison, not a dynamic airline optimizer.</li><li>Assumed full Mint ticket: ${money(f.fullFare)}. Assumed economy fare: ${money(f.economyFare)}. Remaining inventory: ${remaining} seats.</li><li>Existing economy customers contribute only the upgrade fee. If a potential new full-fare customer switches to economy plus an upgrade, the scenario counts that new economy fare and the upgrade instead of a full Mint ticket.</li><li>Protected seats are held for later full-fare requests. They can remain empty if those requests do not arrive.</li><li>Every policy uses the same seeded future-demand draws. No operating costs, cancellations, refunds or loyalty value are modeled.</li><li>The 10th–90th percentile range describes modeled outcome differences. It is not a confidence interval or evidence of real revenue uplift.</li></ul></details></section>`;
}
function renderDetail(){
  const f=cohort(data,state).find(f=>f.id===state.flight);
  if(!f)return heading('Departure detail','Select a departure within your current filters.','RECORD / DEPARTURE')+filters()+empty('This departure is outside the selected cohort','Return to Booking pace or reset the filters to select a departure.');
  const m=metrics(data,state,{flightId:f.id,channel:state.back==='mix'?state.channel:'all'});
  return heading(`${e(f.routeId)} <span style="font-weight:400;color:var(--muted)">/ ${e(f.id)}</span>`,`${fullDate(f.departure)} · ${e(f.departureTime)} local · Data as of ${fullDate(state.asof)}`,'RECORD / DEPARTURE DETAIL')+filters()+`<div class="detail-grid">${inventoryGrid(f,m)}${lineChart(trendSeries(data,state,f.id),{title:'The booking history behind this departure',subtitle:'Cumulative booked passengers · all channels',detail:true})}</div>${bookingTable(m.bookings,{detail:true})}${simulationPanel(f)}`;
}
function renderModel(){
  const baseline=metrics(data,{...DEFAULTS}),checks=validateDataset(data);
  return heading('A foundation you can inspect.','Source, grain, metric definitions and validation stay visible alongside the analysis.','DATA TRUST / SEMANTIC MODEL')+`<div class="notice">All records are reproducible synthetic teaching data. The current Supabase dataset uses the original frozen foundation—not the separate optional refresh-test copy.</div><div class="model-grid"><section class="panel"><div class="panel-header"><h2>Connected data model</h2><a class="text-button" href="/evidence/semantic-model.png" target="_blank" rel="noopener">Open full diagram ↗</a></div><div class="model-flow"><div class="model-node">Route<br><small>6 unique markets</small></div><span class="model-arrow">→</span><div class="model-node">Departure<br><small>48 unique IDs</small></div><span class="model-arrow">→</span><div class="model-node">Booking / inventory / snapshot<br><small>Facts aggregated independently</small></div></div><dl class="definition-list"><div><dt>Bookings · ${data.bookings.length} rows</dt><dd>One generated Mint passenger booking. Key: booking ID. Route and channel support segmentation.</dd></div><div><dt>Snapshots · ${number(data.snapshots.length)} rows</dt><dd>One departure × observation date. Key: departure ID + snapshot date. Cumulative balances are not added across dates.</dd></div><div><dt>Inventory · ${data.flights.length} rows</dt><dd>One modeled capacity value per departure. Booking-channel filters never change its denominator.</dd></div></dl></section><section class="panel"><div class="panel-header"><h2>Load-time validation</h2><span class="validation-badge">${checks.length?'Review required':'Passed'}</span></div><dl class="definition-list"><div><dt>Keys and relationships</dt><dd>Unique route, departure, booking and composite snapshot keys; no unmatched references.</dd></div><div><dt>Balances</dt><dd>Booking counts and fare sums reconcile to each departure and its current snapshot. Inventory limits hold.</dd></div><div><dt>Frozen default values</dt><dd>${money(baseline.revenue)} · ${percent(baseline.utilization)} (${baseline.bookedAll}/${baseline.capacity}) · ${baseline.remaining} remaining · ${baseline.pickup} seven-day bookings.</dd></div><div><dt>Source and timestamps</dt><dd>Supabase · Business cutoff ${fullDate(data.meta.asOf)}. Data fetched ${loadTime?new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}).format(loadTime):'now'}. A recent fetch does not advance the synthetic cutoff.</dd></div></dl><p class="context-code" style="margin-top:18px">Source SHA-256<br>${e(data.meta.sourceSha256)}</p></section></div><section class="panel"><div class="panel-header"><h2>The five-KPI contract</h2><a class="text-button" href="/evidence/kpi-contract.json" target="_blank" rel="noopener">Read contract JSON ↗</a></div><div class="table-wrap"><table><thead><tr><th>KPI</th><th>Definition</th><th>Filter and zero rules</th></tr></thead><tbody><tr><td>Booked revenue · USD</td><td>SUM booking fares through the as-of date</td><td>Selected route/departures/channel. Valid no bookings = $0.</td></tr><tr><td>Average booked fare · USD/passenger</td><td>Revenue / booked passengers</td><td>Recompute from totals. Zero bookings = N/A.</td></tr><tr><td>Booked seat utilization · %</td><td>Booked seats at t / capacity × 100</td><td>All channels. Zero capacity = N/A.</td></tr><tr><td>Remaining seats</td><td>Capacity − booked seats at t</td><td>All channels. Missing snapshots trigger an error.</td></tr><tr><td>7-day booking pickup</td><td>Bookings after t−7 and through t</td><td>Selected booking channel; no cancellations modeled.</td></tr></tbody></table></div><p class="panel-footnote">All five return N/A for an empty departure cohort. As-of dates are supported from 12 Oct through 10 Nov 2026.</p></section><section class="panel" style="margin-top:24px"><h2>Assumptions and limitations</h2><p class="data-description" style="margin:14px 0">Seed ${data.meta.seed}. Fictional departures and fares; 16-seat Mint cabins are a modeling simplification. Airport names supply context, not a claim about real schedules or layouts. No cancellations, refunds, operating costs or identifiable customer data. The optional departure scenario lab is a separate, labeled extension whose outcomes depend on synthetic assumptions.</p><button class="button" data-action="download-data">Download loaded dataset ↓</button></section>`;
}
function setView(html,preserveFilters){
  const filter=preserveFilters&&root.querySelector('#filters');
  if(!filter){root.innerHTML=html;return;}
  // Retain the live form node so native select/date controls keep their keyboard behavior.
  const template=document.createElement('template');template.innerHTML=html;
  const nextFilter=template.content.querySelector('#filters'),before=[],after=[];let passed=false;
  for(const node of [...template.content.childNodes]){
    if(node===nextFilter){passed=true;continue;}(passed?after:before).push(node);
  }
  filter.querySelector('.filter-note').textContent=nextFilter.querySelector('.filter-note').textContent;
  for(const node of [...root.childNodes])if(node!==filter)node.remove();
  filter.before(...before);filter.after(...after);
}
function render({preserveFilters=false}={}){
  if(!data)return;
  document.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===(state.view==='detail'?state.back:state.view);b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});
  try{
    checkContext(data,state);
    setView(({overview:renderOverview,pace:renderPace,mix:renderMix,detail:renderDetail,model:renderModel}[state.view])(),preserveFilters);
    document.title=(state.view==='overview'?'Overview':state.view==='detail'?state.flight:({pace:'Booking pace',mix:'Fare & channel mix',model:'Data & model'}[state.view]))+' · JetBlue Mint Revenue Lab';
    if(state.view==='detail'&&document.querySelector('#scenario-form')){
      runScenario();root.insertAdjacentHTML('beforeend',policyActions.panel());policyActions.mount();
    }
  }catch(error){root.innerHTML=heading('Check the selected context','The model has stopped instead of showing incomplete or misleading values.')+`<div class="notice error" role="alert">${e(error.message)}</div>`+empty('Choose a supported set of filters','Use Reset to return to the validated default portfolio.');}
}
function runScenario(){
  const f=data.flights.find(f=>f.id===state.flight),form=document.querySelector('#scenario-form');if(!f||!form)return;
  const values=new FormData(form),p={price:Number(values.get('price')),protect:Number(values.get('protect')),cannibalization:Number(values.get('cannibalization'))/100,demand:Number(values.get('demand'))};policies.set(f.id,p);
  document.querySelector('#price-output').value=money(p.price);document.querySelector('#protect-output').value=p.protect+' seats';document.querySelector('#switch-output').value=Math.round(p.cannibalization*100)+'%';
  const worlds=createWorlds(f,240,p.demand,SEED),r=evaluate(f,worlds,p),target=document.querySelector('#scenario-results');
  target.innerHTML=`<div class="scenario-results"><div class="scenario-stat"><small>Expected future revenue difference</small><strong class="${r.delta<0?'negative':'delta'}">${r.delta>=0?'+':''}${money(r.delta)}</strong><p class="scenario-explain">Your policy minus holding all remaining seats</p></div><div class="scenario-stat"><small>Modeled outcome range · 10th–90th percentile</small><strong>${money(r.p10)} to ${money(r.p90)}</strong><p class="scenario-explain">Paired scenario differences · uncertainty matters</p></div><div class="scenario-stat"><small>Scenarios where your policy earns more</small><strong>${number(r.winRate*100,1)}%</strong><p class="scenario-explain">Ties are not counted as wins · ${worlds.length} scenarios</p></div></div><div class="summary-line"><span>Expected upgrades: <strong>${number(r.upgrades,1)}</strong></span><span>Expected empty Mint seats: <strong>${number(r.empty,1)}</strong></span><span>Rejected full-fare requests: <strong>${number(r.rejected,1)}</strong></span><span>Switched full-fare shoppers: <strong>${number(r.diverted,1)}</strong></span></div><p class="scenario-explain" style="margin:14px 0">Assumed future requests: ${number(f.futurePremiumMean*p.demand,1)} on average before the shared scenario shock. Modeled future revenue: ${money(r.revenue)} under your policy versus ${money(r.baselineRevenue)} under hold-all. This is revenue, not profit.</p>`;
}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-nav]');if(nav){navigate({view:nav.dataset.nav,flight:'',focus:'',booking:''});return;}
  const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();
  const action=el.dataset.action;
  if(action==='finding')emailActions.openMenu(el);
  else if(['overview','pace','mix'].includes(action))navigate({view:action,flight:'',focus:'',booking:''});
  else if(action==='reset')navigate({...DEFAULTS,view:state.view==='model'?'model':'overview',booking:''},{focusId:'route-filter'});
  else if(action==='pickup')navigate({view:'pace',focus:addDays(state.asof,-6),flight:'',booking:''});
  else if(action==='focus')navigate({view:'pace',focus:el.dataset.date});
  else if(action==='route')navigate({view:'pace',route:el.dataset.route,flight:'',focus:'',booking:''});
  else if(action==='mix-route')navigate({view:'mix',route:el.dataset.route,flight:'',booking:''});
  else if(action==='channel')navigate({channel:el.dataset.channel,view:'mix'});
  else if(action==='clear-focus')navigate({focus:''});
  else if(action==='clear-flight')navigate({flight:'',booking:''});
  else if(action==='investigate')navigate({view:'pace',flight:el.dataset.flight,focus:'',booking:''});
  else if(action==='detail'||action==='booking')navigate({view:'detail',flight:el.dataset.flight,booking:el.dataset.booking||'',back:state.view==='mix'?'mix':'pace'});
  else if(action==='download-data')download('mint-lab-synthetic-dataset.json',JSON.stringify(data,null,2),'application/json');
  else if(action==='export-bookings'){
    const rows=exploreBookings(metrics(data,state,{channel:state.view==='mix'||state.back==='mix'?state.channel:'all',flightId:state.view==='detail'?state.flight:null}).bookings,state).rows;
    const fields=['id','flightId','bookingDate','source','fare'],quote=v=>'"'+String(v).replaceAll('"','""')+'"';
    download('mint-bookings-'+state.asof+'.csv',[fields.join(','),...rows.map(r=>fields.map(k=>quote(r[k])).join(','))].join('\n'),'text/csv');
  }else if(action==='select-booking')navigate({booking:el.dataset.booking},{focusId:'booking-search'});
  else if(action==='record-page')navigate({page:el.dataset.page},{focusId:'booking-search'});
  else if(action==='clear-search')navigate({q:'',page:'1'},{focusId:'booking-search'});
  else if(action==='retry')loadData();
});
document.addEventListener('change',event=>{
  if(event.target.closest('#filters')){
    const form=document.querySelector('#filters');if(!form.checkValidity()){form.reportValidity();return;}
    const changes=Object.fromEntries(new FormData(form)),candidate={...state,...changes};
    try{checkContext(data,candidate);navigate(changes,{preserveFilters:true});}catch(error){message.innerHTML=`<div class="notice error" role="alert">${e(error.message)} The previous valid view is retained.</div>`;}
  }
  if(event.target.id==='channel-filter')navigate({channel:event.target.value},{focusId:'channel-filter'});
  if(event.target.id==='comparison-mode')navigate({compare:event.target.value},{focusId:'comparison-mode'});
  if(event.target.id==='booking-sort')navigate({sort:event.target.value,page:'1'},{focusId:'booking-sort'});
  if(event.target.closest('#scenario-form'))runScenario();
});
document.addEventListener('input',event=>{if(event.target.closest('#scenario-form'))runScenario();});
document.addEventListener('submit',event=>{if(event.target.id==='filters'||event.target.id==='scenario-form')event.preventDefault();
  if(event.target.id==='booking-search-form'){event.preventDefault();navigate({q:document.querySelector('#booking-search').value,page:'1'},{focusId:'booking-search'});}});
window.addEventListener('popstate',()=>{state=readState();message.innerHTML='';render();focusHeading();});
document.querySelector('#refresh').addEventListener('click',()=>loadData());
async function loadData(){
  if(loading)return;loading=true;
  const button=document.querySelector('#refresh'),status=document.querySelector('#load-status'),focused=document.activeElement;
  button.disabled=true;button.textContent='↻ Reading Supabase…';root.setAttribute('aria-busy','true');
  status.hidden=false;status.textContent=data?'Refreshing the portfolio… Your current values stay visible until validation finishes.':'Loading the synthetic portfolio…';
  document.querySelector('#connection').textContent='Reading Supabase…';
  try{
    const configResponse=await fetch('/api/config',{cache:'no-store'});if(!configResponse.ok)throw new Error('Application configuration is unavailable.');
    const config=await configResponse.json();
    const response=await fetch(config.url+'/rest/v1/rpc/mint_lab_dataset',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:'{}',signal:AbortSignal.timeout(20000)});
    if(!response.ok)throw new Error(`Supabase returned ${response.status}. Retry after checking the read-only dataset connection.`);
    const loaded=await response.json(),errors=validateDataset(loaded);if(errors.length)throw new Error(errors.join(' '));
    data=loaded;loadTime=new Date();document.querySelector('#connection').textContent='Supabase · connected';document.querySelector('#connection').classList.remove('error');message.innerHTML='';render();
  }catch(error){
    document.querySelector('#connection').textContent='Connection needs attention';document.querySelector('#connection').classList.add('error');
    const text=error.name==='TimeoutError'?'Supabase did not respond within 20 seconds.':error.message;
    if(data)message.innerHTML=`<div class="notice warning" role="alert">Refresh failed: ${e(text)} Showing the last validated dataset as of ${fullDate(data.meta.asOf)}. <button class="text-button" data-action="retry">Retry</button></div>`;
    else root.innerHTML=`<div class="empty-state" role="alert"><div class="eyebrow">DATA CONNECTION</div><h1>We couldn’t load the portfolio.</h1><p>${e(text)}</p><button class="button primary" data-action="retry">Retry Supabase connection</button></div>`;
  }finally{
    loading=false;button.disabled=false;button.textContent='↻ Refresh data';root.setAttribute('aria-busy','false');status.hidden=true;status.textContent='';
    if(focused?.matches('[data-action="retry"]')&&!document.contains(focused)){
      (data?button:root.querySelector('[data-action="retry"]'))?.focus({preventScroll:true});
    }
  }
}
loadData();

